#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    vector<string> mapa(L);
    int r = -1, c = -1;

    for (int i = 0; i < L; ++i) {
        cin >> mapa[i];
        for (int j = 0; j < C; ++j) {
            if (mapa[i][j] == 'o') {
                r = i;
                c = j;
            }
        }
    }

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    // Marca a posição inicial como visitada
    mapa[r][c] = '.';

    while (true) {
        bool moved = false;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr >= 0 && nr < L && nc >= 0 && nc < C && mapa[nr][nc] == 'H') {
                mapa[nr][nc] = '.'; // Marca como visitado
                r = nr;
                c = nc;
                moved = true;
                break;
            }
        }
        if (!moved) {
            break;
        }
    }

    // Saída com 1-indexado
    cout << r + 1 << " " << c + 1 << "\n";

    return 0;
}
